style.css:
body {
  background: url("https://images.unsplash.com/photo-1630695230041-8909e3204778?fm=jpg&q=80&w=1920") no-repeat center center fixed !important;
  background-size: cover !important;
}

body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.6); /* затемнение */
  z-index: -1;
}
